48	/**
49	 * A {@link NavigableSet} whose contents will never change, with many other important properties
50	 * detailed at {@link ImmutableCollection}.
51	 *
52	 * <p><b>Warning:</b> as with any sorted collection, you are strongly advised not to use a {@link
53	 * Comparator} or {@link Comparable} type whose comparison behavior is <i>inconsistent with
54	 * equals</i>. That is, {@code a.compareTo(b)} or {@code comparator.compare(a, b)} should equal zero
55	 * <i>if and only if</i> {@code a.equals(b)}. If this advice is not followed, the resulting
56	 * collection will not correctly obey its specification.
57	 *
58	 * <p>See the Guava User Guide article on <a href=
59	 * "https://github.com/google/guava/wiki/ImmutableCollectionsExplained">immutable collections</a>.
60	 *
61	 * @author Jared Levy
62	 * @author Louis Wasserman
63	 * @since 2.0 (implements {@code NavigableSet} since 12.0)
64	 */
65	// TODO(benyu): benchmark and optimize all creation paths, which are a mess now
66	@GwtCompatible
67	@SuppressWarnings("serial") // we're overriding default serialization
68	public abstract class ImmutableSortedSet<E> extends ImmutableSet.CachingAsList<E>
69	    implements NavigableSet<E>, SortedIterable<E> {
70	  static final int SPLITERATOR_CHARACTERISTICS =
71	      ImmutableSet.SPLITERATOR_CHARACTERISTICS | Spliterator.SORTED;
72	
73	  /**
74	   * Returns a {@code Collector} that accumulates the input elements into a new {@code
75	   * ImmutableSortedSet}, ordered by the specified comparator.
76	   *
77	   * <p>If the elements contain duplicates (according to the comparator), only the first duplicate
78	   * in encounter order will appear in the result.
79	   *
80	   * @since 21.0
81	   */
82	  public static <E> Collector<E, ?, ImmutableSortedSet<E>> toImmutableSortedSet(
83	      Comparator<? super E> comparator) {
84	    return CollectCollectors.toImmutableSortedSet(comparator);
85	  }
86	
87	  static <E> RegularImmutableSortedSet<E> emptySet(Comparator<? super E> comparator) {
88	    if (Ordering.natural().equals(comparator)) {
89	      @SuppressWarnings("unchecked") // The natural-ordered empty set supports all types.
90	      RegularImmutableSortedSet<E> result =
91	          (RegularImmutableSortedSet<E>) RegularImmutableSortedSet.NATURAL_EMPTY_SET;
92	      return result;
93	    } else {
94	      return new RegularImmutableSortedSet<>(ImmutableList.of(), comparator);
95	    }
96	  }
97	
98	  /**
99	   * Returns the empty immutable sorted set.
100	   *
101	   * <p><b>Performance note:</b> the instance returned is a singleton.
102	   */
103	  @SuppressWarnings("unchecked") // The natural-ordered empty set supports all types.
104	  public static <E> ImmutableSortedSet<E> of() {
105	    return (ImmutableSortedSet<E>) RegularImmutableSortedSet.NATURAL_EMPTY_SET;
106	  }
