58	/**
59	 * Basic implementation of the {@link Multimap} interface. This class represents a multimap as a map
60	 * that associates each key with a collection of values. All methods of {@link Multimap} are
61	 * supported, including those specified as optional in the interface.
62	 *
63	 * <p>To implement a multimap, a subclass must define the method {@link #createCollection()}, which
64	 * creates an empty collection of values for a key.
65	 *
66	 * <p>The multimap constructor takes a map that has a single entry for each distinct key. When you
67	 * insert a key-value pair with a key that isn't already in the multimap, {@code
68	 * AbstractMapBasedMultimap} calls {@link #createCollection()} to create the collection of values
69	 * for that key. The subclass should not call {@link #createCollection()} directly, and a new
70	 * instance should be created every time the method is called.
71	 *
72	 * <p>For example, the subclass could pass a {@link java.util.TreeMap} during construction, and
73	 * {@link #createCollection()} could return a {@link java.util.TreeSet}, in which case the
74	 * multimap's iterators would propagate through the keys and values in sorted order.
75	 *
76	 * <p>Keys and values may be null, as long as the underlying collection classes support null
77	 * elements.
78	 *
79	 * <p>The collections created by {@link #createCollection()} may or may not allow duplicates. If the
80	 * collection, such as a {@link Set}, does not support duplicates, an added key-value pair will
81	 * replace an existing pair with the same key and value, if such a pair is present. With collections
82	 * like {@link List} that allow duplicates, the collection will keep the existing key-value pairs
83	 * while adding a new pair.
84	 *
85	 * <p>This class is not threadsafe when any concurrent operations update the multimap, even if the
86	 * underlying map and {@link #createCollection()} method return threadsafe classes. Concurrent read
87	 * operations will work correctly. To allow concurrent update operations, wrap your multimap with a
88	 * call to {@link Multimaps#synchronizedMultimap}.
89	 *
90	 * <p>For serialization to work, the subclass must specify explicit {@code readObject} and {@code
91	 * writeObject} methods.
92	 *
93	 * @author Jared Levy
94	 * @author Louis Wasserman
95	 */
96	@GwtCompatible
97	@SuppressWarnings("WrongCommentType") // false positive
98	abstract class AbstractMapBasedMultimap<K extends @Nullable Object, V extends @Nullable Object>
99	    extends AbstractMultimap<K, V> implements Serializable {
100	  /*
101	   * Here's an outline of the overall design.
102	   *
103	   * The map variable contains the collection of values associated with each
104	   * key. When a key-value pair is added to a multimap that didn't previously
105	   * contain any values for that key, a new collection generated by
106	   * createCollection is added to the map. That same collection instance
107	   * remains in the map as long as the multimap has any values for the key. If
108	   * all values for the key are removed, the key and collection are removed
109	   * from the map.
110	   *
111	   * The get method returns a WrappedCollection, which decorates the collection
112	   * in the map (if the key is present) or an empty collection (if the key is
113	   * not present). When the collection delegate in the WrappedCollection is
114	   * empty, the multimap may contain subsequently added values for that key. To
115	   * handle that situation, the WrappedCollection checks whether map contains
116	   * an entry for the provided key, and if so replaces the delegate.
117	   */
118	
119	  private transient Map<K, Collection<V>> map;
120	  private transient int totalSize;
121	
122	  /**
123	   * Creates a new multimap that uses the provided map.
124	   *
125	   * @param map place to store the mapping from each key to its corresponding values
126	   * @throws IllegalArgumentException if {@code map} is not empty
127	   */
128	  AbstractMapBasedMultimap(Map<K, Collection<V>> map) {
129	    checkArgument(map.isEmpty());
130	    this.map = map;
131	  }
132	
133	  /** Used during deserialization only. */
134	  final void setMap(Map<K, Collection<V>> map) {
135	    this.map = map;
136	    totalSize = 0;
137	    for (Collection<V> values : map.values()) {
138	      checkArgument(!values.isEmpty());
139	      totalSize += values.size();
140	    }
141	  }
