144	   * Creates an unmodifiable, empty collection of values.
145	   *
146	   * <p>This is used in {@link #removeAll} on an empty key.
147	   */
148	  Collection<V> createUnmodifiableEmptyCollection() {
149	    return unmodifiableCollectionSubclass(createCollection());
150	  }
