152	  /**
153	   * Creates the collection of values for a single key.
154	   *
155	   * <p>Collections with weak, soft, or phantom references are not supported. Each call to {@code
156	   * createCollection} should create a new instance.
157	   *
158	   * <p>The returned collection class determines whether duplicate key-value pairs are allowed.
159	   *
160	   * @return an empty collection of values
161	   */
162	  abstract Collection<V> createCollection();
