194	  @Override
195	  public boolean put(@ParametricNullness K key, @ParametricNullness V value) {
196	    Collection<V> collection = map.get(key);
197	    if (collection == null) {
198	      collection = createCollection(key);
199	      if (collection.add(value)) {
200	        totalSize++;
201	        map.put(key, collection);
202	        return true;
203	      } else {
204	        throw new AssertionError("New Collection violated the Collection spec");
205	      }
206	    } else if (collection.add(value)) {
207	      totalSize++;
208	      return true;
209	    } else {
210	      return false;
211	    }
212	  }
