214	  private Collection<V> getOrCreateCollection(@ParametricNullness K key) {
215	    Collection<V> collection = map.get(key);
216	    if (collection == null) {
217	      collection = createCollection(key);
218	      map.put(key, collection);
219	    }
220	    return collection;
221	  }
