228	   * <p>The returned collection is immutable.
229	   */
230	  @Override
231	  public Collection<V> replaceValues(@ParametricNullness K key, Iterable<? extends V> values) {
232	    Iterator<? extends V> iterator = values.iterator();
233	    if (!iterator.hasNext()) {
234	      return removeAll(key);
235	    }
236	
237	    // TODO(lowasser): investigate atomic failure?
238	    Collection<V> collection = getOrCreateCollection(key);
239	    Collection<V> oldValues = createCollection();
240	    oldValues.addAll(collection);
241	
242	    totalSize -= collection.size();
243	    collection.clear();
244	
245	    while (iterator.hasNext()) {
246	      if (collection.add(iterator.next())) {
247	        totalSize++;
248	      }
249	    }
250	
251	    return unmodifiableCollectionSubclass(oldValues);
252	  }
