261	    Collection<V> collection = map.remove(key);
262	
263	    if (collection == null) {
264	      return createUnmodifiableEmptyCollection();
265	    }
266	
267	    Collection<V> output = createCollection();
268	    output.addAll(collection);
269	    totalSize -= collection.size();
270	    collection.clear();
271	
272	    return unmodifiableCollectionSubclass(output);
273	  }
