55	@J2ktIncompatible
56	@Immutable
57	@SuppressWarnings("IdentifierName") // the best we could do for adjacent digit blocks
58	final class Murmur3_32HashFunction extends AbstractHashFunction implements Serializable {
59	  static final HashFunction MURMUR3_32 =
60	      new Murmur3_32HashFunction(0, /* supplementaryPlaneFix= */ false);
61	  static final HashFunction MURMUR3_32_FIXED =
62	      new Murmur3_32HashFunction(0, /* supplementaryPlaneFix= */ true);
63	
64	  // We can include the non-BMP fix here because Hashing.goodFastHash stresses that the hash is a
65	  // temporary-use one. Therefore it shouldn't be persisted.
66	  static final HashFunction GOOD_FAST_HASH_32 =
67	      new Murmur3_32HashFunction(GOOD_FAST_HASH_SEED, /* supplementaryPlaneFix= */ true);
68	
69	  private static final int CHUNK_SIZE = 4;
70	
71	  private static final int C1 = 0xcc9e2d51;
72	  private static final int C2 = 0x1b873593;
73	
74	  private final int seed;
75	  private final boolean supplementaryPlaneFix;
76	
77	  Murmur3_32HashFunction(int seed, boolean supplementaryPlaneFix) {
78	    this.seed = seed;
79	    this.supplementaryPlaneFix = supplementaryPlaneFix;
80	  }
81	
82	  @Override
83	  public int bits() {
84	    return 32;
85	  }
86	
87	  @Override
88	  public Hasher newHasher() {
89	    return new Murmur3_32Hasher(seed);
90	  }
91	
92	  @Override
93	  public String toString() {
94	    return "Hashing.murmur3_32(" + seed + ")";
95	  }
96	
97	  @Override
98	  public boolean equals(@Nullable Object object) {
99	    if (object instanceof Murmur3_32HashFunction) {
100	      Murmur3_32HashFunction other = (Murmur3_32HashFunction) object;
101	      return seed == other.seed && supplementaryPlaneFix == other.supplementaryPlaneFix;
102	    }
103	    return false;
104	  }
105	
106	  @Override
107	  public int hashCode() {
108	    return getClass().hashCode() ^ seed;
109	  }
110	
111	  @Override
112	  public HashCode hashInt(int input) {
113	    int k1 = mixK1(input);
114	    int h1 = mixH1(seed, k1);
115	
116	    return fmix(h1, Ints.BYTES);
117	  }
118	
119	  @Override
120	  public HashCode hashLong(long input) {
121	    int low = (int) input;
122	    int high = (int) (input >>> 32);
123	
124	    int k1 = mixK1(low);
125	    int h1 = mixH1(seed, k1);
126	
127	    k1 = mixK1(high);
128	    h1 = mixH1(h1, k1);
129	
130	    return fmix(h1, Longs.BYTES);
131	  }
132	
133	  @Override
134	  public HashCode hashUnencodedChars(CharSequence input) {
135	    int h1 = seed;
136	
137	    // step through the CharSequence 2 chars at a time
138	    for (int i = 1; i < input.length(); i += 2) {
139	      int k1 = input.charAt(i - 1) | (input.charAt(i) << 16);
140	      k1 = mixK1(k1);
141	      h1 = mixH1(h1, k1);
142	    }
143	
144	    // deal with any remaining characters
145	    if ((input.length() & 1) == 1) {
146	      int k1 = input.charAt(input.length() - 1);
147	      k1 = mixK1(k1);
148	      h1 ^= k1;
149	    }
150	
151	    return fmix(h1, Chars.BYTES * input.length());
152	  }
153	
154	  @Override
155	  public HashCode hashString(CharSequence input, Charset charset) {
156	    if (charset.equals(UTF_8)) {
157	      int utf16Length = input.length();
158	      int h1 = seed;
159	      int i = 0;
160	      int len = 0;
161	
162	      // This loop optimizes for pure ASCII.
163	      while (i + 4 <= utf16Length) {
164	        char c0 = input.charAt(i);
165	        char c1 = input.charAt(i + 1);
166	        char c2 = input.charAt(i + 2);
167	        char c3 = input.charAt(i + 3);
168	        if (c0 < 0x80 && c1 < 0x80 && c2 < 0x80 && c3 < 0x80) {
169	          int k1 = c0 | (c1 << 8) | (c2 << 16) | (c3 << 24);
170	          k1 = mixK1(k1);
171	          h1 = mixH1(h1, k1);
172	          i += 4;
173	          len += 4;
174	        } else {
175	          break;
176	        }
177	      }
178	
179	      long buffer = 0;
180	      int shift = 0;
181	      for (; i < utf16Length; i++) {
182	        char c = input.charAt(i);
183	        if (c < 0x80) {
184	          buffer |= (long) c << shift;
185	          shift += 8;
186	          len++;
187	        } else if (c < 0x800) {
188	          buffer |= charToTwoUtf8Bytes(c) << shift;
189	          shift += 16;
190	          len += 2;
191	        } else if (c < Character.MIN_SURROGATE || c > Character.MAX_SURROGATE) {
192	          buffer |= charToThreeUtf8Bytes(c) << shift;
193	          shift += 24;
194	          len += 3;
195	        } else {
196	          int codePoint = Character.codePointAt(input, i);
197	          if (codePoint == c) {
198	            // not a valid code point; let the JDK handle invalid Unicode
199	            return hashBytes(input.toString().getBytes(charset));
200	          }
201	          i++;
202	          buffer |= codePointToFourUtf8Bytes(codePoint) << shift;
203	          if (supplementaryPlaneFix) { // bug compatibility: earlier versions did not have this add
204	            shift += 32;
205	          }
206	          len += 4;
207	        }
208	
209	        if (shift >= 32) {
210	          int k1 = mixK1((int) buffer);
211	          h1 = mixH1(h1, k1);
212	          buffer = buffer >>> 32;
213	          shift -= 32;
214	        }
215	      }
216	
217	      int k1 = mixK1((int) buffer);
218	      h1 ^= k1;
219	      return fmix(h1, len);
220	    } else {
221	      return hashBytes(input.toString().getBytes(charset));
222	    }
223	  }
224	
225	  @Override
226	  public HashCode hashBytes(byte[] input, int off, int len) {
227	    checkPositionIndexes(off, off + len, input.length);
228	    int h1 = seed;
229	    int i;
230	    for (i = 0; i + CHUNK_SIZE <= len; i += CHUNK_SIZE) {
231	      int k1 = mixK1(getIntLittleEndian(input, off + i));
232	      h1 = mixH1(h1, k1);
233	    }
234	
235	    int k1 = 0;
236	    for (int shift = 0; i < len; i++, shift += 8) {
237	      k1 ^= toUnsignedInt(input[off + i]) << shift;
238	    }
239	    h1 ^= mixK1(k1);
240	    return fmix(h1, len);
241	  }
242	
243	  private static int getIntLittleEndian(byte[] input, int offset) {
244	    return Ints.fromBytes(input[offset + 3], input[offset + 2], input[offset + 1], input[offset]);
245	  }
246	
247	  private static int mixK1(int k1) {
248	    k1 *= C1;
249	    k1 = Integer.rotateLeft(k1, 15);
250	    k1 *= C2;
251	    return k1;
252	  }
253	
254	  private static int mixH1(int h1, int k1) {
255	    h1 ^= k1;
256	    h1 = Integer.rotateLeft(h1, 13);
257	    h1 = h1 * 5 + 0xe6546b64;
258	    return h1;
259	  }
260	
261	  // Finalization mix - force all bits of a hash block to avalanche
262	  private static HashCode fmix(int h1, int length) {
263	    h1 ^= length;
264	    h1 ^= h1 >>> 16;
265	    h1 *= 0x85ebca6b;
266	    h1 ^= h1 >>> 13;
267	    h1 *= 0xc2b2ae35;
268	    h1 ^= h1 >>> 16;
269	    return HashCode.fromInt(h1);
270	  }
271	
272	  private static final class Murmur3_32Hasher extends AbstractHasher {
273	    private int h1;
274	    private long buffer;
275	    private int shift;
276	    private int length;
277	    private boolean isDone;
278	
279	    Murmur3_32Hasher(int seed) {
280	      this.h1 = seed;
281	      this.length = 0;
282	      isDone = false;
283	    }
284	
285	    private void update(int nBytes, long update) {
286	      // 1 <= nBytes <= 4
287	      buffer |= (update & 0xFFFFFFFFL) << shift;
288	      shift += nBytes * 8;
289	      length += nBytes;
290	
291	      if (shift >= 32) {
292	        h1 = mixH1(h1, mixK1((int) buffer));
293	        buffer >>>= 32;
294	        shift -= 32;
295	      }
296	    }
297	
298	    @CanIgnoreReturnValue
299	    @Override
300	    public Hasher putByte(byte b) {
301	      update(1, b & 0xFF);
302	      return this;
303	    }
304	
305	    @CanIgnoreReturnValue
306	    @Override
307	    public Hasher putBytes(byte[] bytes, int off, int len) {
308	      checkPositionIndexes(off, off + len, bytes.length);
309	      int i;
310	      for (i = 0; i + 4 <= len; i += 4) {
311	        update(4, getIntLittleEndian(bytes, off + i));
312	      }
313	      for (; i < len; i++) {
314	        putByte(bytes[off + i]);
315	      }
316	      return this;
317	    }
318	
319	    @CanIgnoreReturnValue
320	    @Override
321	    public Hasher putBytes(ByteBuffer buffer) {
322	      ByteOrder bo = buffer.order();
323	      buffer.order(ByteOrder.LITTLE_ENDIAN);
324	      while (buffer.remaining() >= 4) {
325	        putInt(buffer.getInt());
326	      }
327	      while (buffer.hasRemaining()) {
328	        putByte(buffer.get());
329	      }
330	      buffer.order(bo);
331	      return this;
332	    }
333	
334	    @CanIgnoreReturnValue
335	    @Override
336	    public Hasher putInt(int i) {
337	      update(4, i);
338	      return this;
339	    }
340	
341	    @CanIgnoreReturnValue
342	    @Override
343	    public Hasher putLong(long l) {
344	      update(4, (int) l);
345	      update(4, l >>> 32);
346	      return this;
347	    }
348	
349	    @CanIgnoreReturnValue
350	    @Override
351	    public Hasher putChar(char c) {
352	      update(2, c);
353	      return this;
354	    }
355	
356	    @CanIgnoreReturnValue
357	    @Override
358	    public Hasher putString(CharSequence input, Charset charset) {
359	      if (charset.equals(UTF_8)) {
360	        int utf16Length = input.length();
361	        int i = 0;
362	
363	        // This loop optimizes for pure ASCII.
364	        while (i + 4 <= utf16Length) {
365	          char c0 = input.charAt(i);
366	          char c1 = input.charAt(i + 1);
367	          char c2 = input.charAt(i + 2);
368	          char c3 = input.charAt(i + 3);
369	          if (c0 < 0x80 && c1 < 0x80 && c2 < 0x80 && c3 < 0x80) {
370	            update(4, c0 | (c1 << 8) | (c2 << 16) | (c3 << 24));
371	            i += 4;
372	          } else {
373	            break;
374	          }
375	        }
376	
377	        for (; i < utf16Length; i++) {
378	          char c = input.charAt(i);
379	          if (c < 0x80) {
380	            update(1, c);
381	          } else if (c < 0x800) {
382	            update(2, charToTwoUtf8Bytes(c));
383	          } else if (c < Character.MIN_SURROGATE || c > Character.MAX_SURROGATE) {
384	            update(3, charToThreeUtf8Bytes(c));
385	          } else {
386	            int codePoint = Character.codePointAt(input, i);
387	            if (codePoint == c) {
388	              // fall back to JDK getBytes instead of trying to handle invalid surrogates ourselves
389	              putBytes(input.subSequence(i, utf16Length).toString().getBytes(charset));
390	              return this;
391	            }
392	            i++;
393	            update(4, codePointToFourUtf8Bytes(codePoint));
394	          }
395	        }
396	        return this;
397	      } else {
398	        return super.putString(input, charset);
399	      }
400	    }
401	
402	    @Override
403	    public HashCode hash() {
404	      checkState(!isDone);
405	      isDone = true;
406	      h1 ^= mixK1((int) buffer);
407	      return fmix(h1, length);
408	    }
409	  }
410	
411	  private static long codePointToFourUtf8Bytes(int codePoint) {
412	    // codePoint has at most 21 bits
413	    return ((0xFL << 4) | (codePoint >>> 18))
414	        | ((0x80L | (0x3F & (codePoint >>> 12))) << 8)
415	        | ((0x80L | (0x3F & (codePoint >>> 6))) << 16)
416	        | ((0x80L | (0x3F & codePoint)) << 24);
417	  }
418	
419	  private static long charToThreeUtf8Bytes(char c) {
420	    return ((0x7L << 5) | (c >>> 12))
421	        | ((0x80 | (0x3F & (c >>> 6))) << 8)
422	        | ((0x80 | (0x3F & c)) << 16);
423	  }
424	
425	  private static long charToTwoUtf8Bytes(char c) {
426	    // c has at most 11 bits
427	    return ((0x3L << 6) | (c >>> 6)) | ((0x80 | (0x3F & c)) << 8);
428	  }
429	
430	  private static final long serialVersionUID = 0L;
431	}
