70	  @Override
71	  public String toString() {
72	    return "Hashing.murmur3_128(" + seed + ")";
73	  }
74	
75	  @Override
76	  public boolean equals(@Nullable Object object) {
77	    if (object instanceof Murmur3_128HashFunction) {
78	      Murmur3_128HashFunction other = (Murmur3_128HashFunction) object;
79	      return seed == other.seed;
80	    }
81	    return false;
82	  }
83	
84	  @Override
85	  public int hashCode() {
86	    return getClass().hashCode() ^ seed;
87	  }
88	
89	  private static final class Murmur3_128Hasher extends AbstractStreamingHasher {
90	    private static final int CHUNK_SIZE = 16;
91	    private static final long C1 = 0x87c37b91114253d5L;
92	    private static final long C2 = 0x4cf5ad432745937fL;
93	    private long h1;
94	    private long h2;
95	    private int length;
96	
97	    Murmur3_128Hasher(int seed) {
98	      super(CHUNK_SIZE);
99	      this.h1 = seed;
100	      this.h2 = seed;
101	      this.length = 0;
102	    }
103	
104	    @Override
105	    protected void process(ByteBuffer bb) {
106	      long k1 = bb.getLong();
107	      long k2 = bb.getLong();
108	      bmix64(k1, k2);
109	      length += CHUNK_SIZE;
110	    }
111	
112	    private void bmix64(long k1, long k2) {
113	      h1 ^= mixK1(k1);
114	
115	      h1 = Long.rotateLeft(h1, 27);
116	      h1 += h2;
117	      h1 = h1 * 5 + 0x52dce729;
118	
119	      h2 ^= mixK2(k2);
120	
121	      h2 = Long.rotateLeft(h2, 31);
122	      h2 += h1;
123	      h2 = h2 * 5 + 0x38495ab5;
124	    }
125	
126	    @Override
127	    protected void processRemaining(ByteBuffer bb) {
128	      long k1 = 0;
129	      long k2 = 0;
130	      length += bb.remaining();
131	      switch (bb.remaining()) {
132	        case 15:
133	          k2 ^= (long) toUnsignedInt(bb.get(14)) << 48; // fall through
134	        case 14:
135	          k2 ^= (long) toUnsignedInt(bb.get(13)) << 40; // fall through
136	        case 13:
137	          k2 ^= (long) toUnsignedInt(bb.get(12)) << 32; // fall through
138	        case 12:
139	          k2 ^= (long) toUnsignedInt(bb.get(11)) << 24; // fall through
140	        case 11:
141	          k2 ^= (long) toUnsignedInt(bb.get(10)) << 16; // fall through
142	        case 10:
143	          k2 ^= (long) toUnsignedInt(bb.get(9)) << 8; // fall through
144	        case 9:
145	          k2 ^= (long) toUnsignedInt(bb.get(8)); // fall through
146	        case 8:
147	          k1 ^= bb.getLong();
148	          break;
149	        case 7:
150	          k1 ^= (long) toUnsignedInt(bb.get(6)) << 48; // fall through
151	        case 6:
152	          k1 ^= (long) toUnsignedInt(bb.get(5)) << 40; // fall through
153	        case 5:
154	          k1 ^= (long) toUnsignedInt(bb.get(4)) << 32; // fall through
155	        case 4:
156	          k1 ^= (long) toUnsignedInt(bb.get(3)) << 24; // fall through
157	        case 3:
158	          k1 ^= (long) toUnsignedInt(bb.get(2)) << 16; // fall through
159	        case 2:
160	          k1 ^= (long) toUnsignedInt(bb.get(1)) << 8; // fall through
161	        case 1:
162	          k1 ^= (long) toUnsignedInt(bb.get(0));
163	          break;
164	        default:
165	          throw new AssertionError("Should never get here.");
166	      }
167	      h1 ^= mixK1(k1);
168	      h2 ^= mixK2(k2);
169	    }
170	
171	    @Override
172	    protected HashCode makeHash() {
173	      h1 ^= length;
174	      h2 ^= length;
175	
176	      h1 += h2;
177	      h2 += h1;
178	
179	      h1 = fmix64(h1);
180	      h2 = fmix64(h2);
181	
182	      h1 += h2;
183	      h2 += h1;
184	
185	      return HashCode.fromBytesNoCopy(
186	          ByteBuffer.wrap(new byte[CHUNK_SIZE])
187	              .order(ByteOrder.LITTLE_ENDIAN)
188	              .putLong(h1)
189	              .putLong(h2)
190	              .array());
191	    }
192	
193	    private static long fmix64(long k) {
194	      k ^= k >>> 33;
195	      k *= 0xff51afd7ed558ccdL;
196	      k ^= k >>> 33;
197	      k *= 0xc4ceb9fe1a85ec53L;
198	      k ^= k >>> 33;
199	      return k;
200	    }
201	
202	    private static long mixK1(long k1) {
203	      k1 *= C1;
204	      k1 = Long.rotateLeft(k1, 31);
205	      k1 *= C2;
206	      return k1;
207	    }
208	
209	    private static long mixK2(long k2) {
210	      k2 *= C2;
211	      k2 = Long.rotateLeft(k2, 33);
212	      k2 *= C1;
213	      return k2;
214	    }
215	  }
216	
217	  private static final long serialVersionUID = 0L;
218	}
