15	package com.google.common.eventbus;
16	
17	import static com.google.common.base.Preconditions.checkNotNull;
18	import static java.util.Objects.requireNonNull;
19	
20	import java.util.ArrayDeque;
21	import java.util.Iterator;
22	import java.util.Queue;
23	import java.util.concurrent.ConcurrentLinkedQueue;
24	
25	/**
26	 * Handler for dispatching events to subscribers, providing different event ordering guarantees that
27	 * make sense for different situations.
28	 *
29	 * <p><b>Note:</b> The dispatcher is orthogonal to the subscriber's {@code Executor}. The dispatcher
30	 * controls the order in which events are dispatched, while the executor controls how (i.e. on which
31	 * thread) the subscriber is actually called when an event is dispatched to it.
32	 *
33	 * @author Colin Decker
34	 */
35	abstract class Dispatcher {
36	
37	  /**
38	   * Returns a dispatcher that queues events that are posted reentrantly on a thread that is already
39	   * dispatching an event, guaranteeing that all events posted on a single thread are dispatched to
40	   * all subscribers in the order they are posted.
41	   *
42	   * <p>When all subscribers are dispatched to using a <i>direct</i> executor (which dispatches on
43	   * the same thread that posts the event), this yields a breadth-first dispatch order on each
44	   * thread. That is, all subscribers to a single event A will be called before any subscribers to
45	   * any events B and C that are posted to the event bus by the subscribers to A.
46	   */
47	  static Dispatcher perThreadDispatchQueue() {
48	    return new PerThreadQueuedDispatcher();
49	  }
50	
51	  /**
52	   * Returns a dispatcher that queues events that are posted in a single global queue. This behavior
53	   * matches the original behavior of AsyncEventBus exactly, but is otherwise not especially useful.
54	   * For async dispatch, an {@linkplain #immediate() immediate} dispatcher should generally be
55	   * preferable.
56	   */
57	  static Dispatcher legacyAsync() {
58	    return new LegacyAsyncDispatcher();
59	  }
60	
61	  /**
62	   * Returns a dispatcher that dispatches events to subscribers immediately as they're posted
63	   * without using an intermediate queue to change the dispatch order. This is effectively a
64	   * depth-first dispatch order, vs. breadth-first when using a queue.
65	   */
66	  static Dispatcher immediate() {
67	    return ImmediateDispatcher.INSTANCE;
68	  }
69	
70	  /** Dispatches the given {@code event} to the given {@code subscribers}. */
71	  abstract void dispatch(Object event, Iterator<Subscriber> subscribers);
72	
73	  /** Implementation of a {@link #perThreadDispatchQueue()} dispatcher. */
74	  private static final class PerThreadQueuedDispatcher extends Dispatcher {
75	
76	    // This dispatcher matches the original dispatch behavior of EventBus.
77	
78	    /** Per-thread queue of events to dispatch. */
79	    @SuppressWarnings("ThreadLocalUsage") // Each Dispatcher needs its own state.
80	    private final ThreadLocal<Queue<Event>> queue =
81	        new ThreadLocal<Queue<Event>>() {
82	          @Override
83	          protected Queue<Event> initialValue() {
84	            return new ArrayDeque<>();
85	          }
86	        };
87	
88	    /** Per-thread dispatch state, used to avoid reentrant event dispatching. */
89	    @SuppressWarnings("ThreadLocalUsage") // Each Dispatcher needs its own state.
90	    private final ThreadLocal<Boolean> dispatching =
91	        new ThreadLocal<Boolean>() {
92	          @Override
93	          protected Boolean initialValue() {
94	            return false;
95	          }
96	        };
97	
98	    @Override
99	    void dispatch(Object event, Iterator<Subscriber> subscribers) {
100	      checkNotNull(event);
101	      checkNotNull(subscribers);
102	      // requireNonNull accommodates Android's @RecentlyNullable annotation on ThreadLocal.get
103	      Queue<Event> queueForThread = requireNonNull(queue.get());
104	      queueForThread.offer(new Event(event, subscribers));
105	
106	      if (!dispatching.get()) {
107	        dispatching.set(true);
108	        try {
109	          Event nextEvent;
110	          while ((nextEvent = queueForThread.poll()) != null) {
111	            while (nextEvent.subscribers.hasNext()) {
112	              nextEvent.subscribers.next().dispatchEvent(nextEvent.event);
113	            }
114	          }
115	        } finally {
116	          dispatching.remove();
117	          queue.remove();
118	        }
119	      }
120	    }
121	
122	    private static final class Event {
123	      private final Object event;
124	      private final Iterator<Subscriber> subscribers;
125	
126	      private Event(Object event, Iterator<Subscriber> subscribers) {
127	        this.event = event;
128	        this.subscribers = subscribers;
129	      }
130	    }
131	  }
132	
133	  /** Implementation of a {@link #legacyAsync()} dispatcher. */
134	  private static final class LegacyAsyncDispatcher extends Dispatcher {
135	
136	    // This dispatcher matches the original dispatch behavior of AsyncEventBus.
137	    //
138	    // We can't really make any guarantees about the overall dispatch order for this dispatcher in
139	    // a multithreaded environment for a couple of reasons:
140	    //
141	    // 1. Subscribers to events posted on different threads can be interleaved with each other
142	    //    freely. (A event on one thread, B event on another could yield any of
143	    //    [a1, a2, a3, b1, b2], [a1, b2, a2, a3, b2], [a1, b2, b3, a2, a3], etc.)
144	    // 2. It's possible for subscribers to actually be dispatched to in a different order than they
145	    //    were added to the queue. It's easily possible for one thread to take the head of the
146	    //    queue, immediately followed by another thread taking the next element in the queue. That
147	    //    second thread can then dispatch to the subscriber it took before the first thread does.
148	    //
149	    // All this makes me really wonder if there's any value in queueing here at all. A dispatcher
150	    // that simply loops through the subscribers and dispatches the event to each would actually
151	    // probably provide a stronger order guarantee, though that order would obviously be different
152	    // in some cases.
153	
154	    /** Global event queue. */
155	    private final ConcurrentLinkedQueue<EventWithSubscriber> queue = new ConcurrentLinkedQueue<>();
156	
157	    @Override
158	    void dispatch(Object event, Iterator<Subscriber> subscribers) {
159	      checkNotNull(event);
160	      while (subscribers.hasNext()) {
161	        queue.add(new EventWithSubscriber(event, subscribers.next()));
162	      }
163	
164	      EventWithSubscriber e;
165	      while ((e = queue.poll()) != null) {
166	        e.subscriber.dispatchEvent(e.event);
167	      }
168	    }
169	
170	    private static final class EventWithSubscriber {
171	      private final Object event;
172	      private final Subscriber subscriber;
173	
174	      private EventWithSubscriber(Object event, Subscriber subscriber) {
175	        this.event = event;
176	        this.subscriber = subscriber;
177	      }
178	    }
179	  }
180	
181	  /** Implementation of {@link #immediate()}. */
182	  private static final class ImmediateDispatcher extends Dispatcher {
183	    private static final ImmediateDispatcher INSTANCE = new ImmediateDispatcher();
184	
185	    @Override
186	    void dispatch(Object event, Iterator<Subscriber> subscribers) {
187	      checkNotNull(event);
188	      while (subscribers.hasNext()) {
189	        subscribers.next().dispatchEvent(event);
190	      }
191	    }
192	  }
193	}
